import React, { useState, useEffect, useContext } from "react";
import { useParams, useNavigate } from "react-router-dom";
import axios from "axios";
import { OrderContext } from "./OrderContext";

const UpdateOrder = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const { setOrdersChanged } = useContext(OrderContext);

  const [orderData, setOrderData] = useState({
    firstName: "",
    lastName: "",
    email: "",
    phoneNumber: "",
    address: "",
    city: "",
    orderId: "",
    specialInstructions: "",
    pickupTime: "",
    orderStatus: "",
  });

  useEffect(() => {
    const fetchOrderDetails = async () => {
      try {
        const response = await axios.get(`http://localhost:5000/orders/${id}`);
        setOrderData(response.data); // Make sure response.data is correctly structured
      } catch (err) {
        console.error("Error fetching order details:", err);
      }
    };

    fetchOrderDetails();
  }, [id]);

  const handleChange = (e) => {
    setOrderData({ ...orderData, [e.target.name]: e.target.value });
  };

  const updateOrder = async (e) => {
    e.preventDefault();
    try {
      await axios.put(`http://localhost:5000/orders/${id}`, orderData);
      setOrdersChanged((prev) => !prev);
      alert("✅ Order Updated Successfully!");
      navigate("/all-orders");
    } catch (err) {
      console.error("Update Error:", err);
      alert("❌ Failed to update order. Try again.");
    }
  };

  return (
    <div style={{ padding: "20px", backgroundColor: "#f8f9fa", minHeight: "100vh" }}>
      <h2 style={{ textAlign: "center" }}>Update Order</h2>
      <form onSubmit={updateOrder} style={{ display: "flex", flexDirection: "column", gap: "10px", maxWidth: "400px", margin: "auto" }}>
        {Object.keys(orderData).map((key) => (
          <input 
            key={key}
            type="text"
            name={key}
            value={orderData[key] || ""}  // Ensure it's not an object
            onChange={handleChange}
            placeholder={key}
            required
          />
        ))}
        <button type="submit" style={{ padding: "10px", backgroundColor: "blue", color: "white", border: "none", cursor: "pointer" }}>
          Update
        </button>
      </form>
    </div>
  );
};

export default UpdateOrder;
